state.layerId='title';state.studioPage='ゲーム';state.layers=[];state.layerHistory=[];
function resetLayers(){const t=currentTemplate(),b=currentBrand();state.layers=[{id:'logo',name:'브랜드 로고',type:'텍스트',text:b.short,color:t.ink,size:13,visible:true},{id:'title',name:'메인 제목',type:'텍스트',text:t.headline.replace(/<br>/g,'\n'),color:t.ink,size:24,visible:true},{id:'copy',name:'안내 문구',type:'텍스트',text:'게임에 참여하고 브랜드의 선물을 만나보세요.',color:'#ac91a2',size:11,visible:true},{id:'game',name:t.type+' 게임',type:'게임 블록',text:t.type,color:t.accent,size:160,visible:true},{id:'button',name:'참여 버튼',type:'버튼',text:t.kind==='wheel'?'룰렛 돌리기':t.kind==='quiz'?'퀴즈 시작하기':'게임 시작하기',color:t.accent,size:12,visible:true}];state.layerId='title'}resetLayers();state.studioPage='게임';
const scopeShell=shell;shell=function(body){let h=scopeShell(body),r=route(),b=currentBrand();let scope=r==='home'||r==='events'||r==='workspace'||r==='design'?'대행사 전체 브랜드':r==='whitelabel'?'대행사 공통 · 고객 공유 브랜딩':r==='templates'?'공용 템플릿 · '+b.name+'에 적용':b.name+(state.eventName?' / '+state.eventName:'');h=h.replace('<div class="agency">스테이지원 커뮤니케이션</div>',`<div class="agency">스테이지원 커뮤니케이션</div><div class="workspace-switcher"><label for="scope-brand">현재 브랜드</label><select id="scope-brand">${brandOptions()}</select></div>`);h=h.replace('CREATE & SHARE',`브랜드 작업 <b>· ${esc(b.short)}</b>`);h=h.replace('<span>게임 템플릿</span>','<span>게임 템플릿</span><small class="scope-global">공용</small>');h=h.replace('<span>화이트라벨</span>','<span>화이트라벨</span><small class="scope-global">대행사</small>');h=h.replace(/<span>워크스페이스 <span style="margin:0 10px">\/<\/span> <strong>스테이지원 커뮤니케이션<\/strong><\/span>/,`<span class="scope-label">${esc(scope)}</span>`);return h};
const scopeSteps=steps;steps=function(active){let h=scopeSteps(active);h=h.replace(/<select class="event-brand-select"[\s\S]*?<\/select>/,`<span class="badge">${esc(currentBrand().short)}</span>`);return h};
function startGuide(){return `<section class="guide-top"><div class="guide-top-head"><h2>시작 가이드</h2><span class="mini-label">다음 할 일부터 차근차근</span></div><div class="guide-items"><a href="#whitelabel" class="done"><b>✓</b>대행사 브랜딩</a><a href="#workspace" class="done"><b>✓</b>브랜드 준비</a><a href="#event-basic"><b>3</b>첫 행사 만들기</a><a href="#workspace-detail"><b>4</b>게스트 초대</a><a href="#brand-report"><b>5</b>성과 공유</a></div></section>`}
const guideHome=home;home=function(){let h=guideHome();return h.replace('<div class="content">','<div class="content">'+startGuide())};const guideWhitelabel=whitelabel;whitelabel=function(){let h=guideWhitelabel();h=h.replace(/<section class="panel mt"><div class="panel-head"><h2>시작 가이드<\/h2>[\s\S]*?<\/section>/,'');return h.replace('<div class="content">','<div class="content">'+startGuide())};
function layerCanvas(){const t=currentTemplate();let list=state.layers.filter(l=>l.visible);if(state.studioPage==='참여 시작')list=list.filter(l=>l.id!=='game');return `<div class="editable-phone" data-component="EditableCanvas" style="--stage:${t.stage};--paper:${t.paper};--ink:${t.ink};--accent:${state.layers.find(l=>l.id==='game').color};background:${t.paper}">${list.map(l=>`<div data-layer="${l.id}" class="editable-layer ${l.id}-layer ${state.layerId===l.id?'selected':''}" style="${l.id==='game'?'':l.id==='button'?`background:${l.color};font-size:${l.size}px`:`color:${l.color};font-size:${l.size}px`}">${l.id==='game'?gameSketch(t):esc(state.studioPage==='결과'&&l.id==='title'?'축하합니다!\n선물이 도착했어요.':l.text)}</div>`).join('')}</div>`}
function properties(){const l=state.layers.find(l=>l.id===state.layerId)||state.layers[0];return `<h3>${esc(l.name)}</h3><div class="properties-type">${l.type} 레이어</div>${l.id==='game'?`<div class="alert purple" style="font-size:10px">${currentTemplate().type} 템플릿의 게임 영역입니다.<br>당첨·지급 방식은 경품 설정에서 편집합니다.</div>`:`<div class="field"><label for="layer-text">${l.id==='button'?'버튼 문구':'텍스트'}</label><textarea id="layer-text">${esc(l.text)}</textarea></div>`}<div class="field"><label for="layer-color">${l.id==='button'?'버튼 배경':l.id==='game'?'게임 대표 색상':'글자 색상'}</label><div class="property-row"><input id="layer-color" type="color" value="${l.color}"><input value="${l.color}" id="layer-color-hex" aria-label="색상 코드" readonly></div></div>${l.id==='game'?'':`<div class="field"><label for="layer-size">글자 크기 (px)</label><input id="layer-size" type="number" min="8" max="48" value="${l.size}"></div>`}<div class="field"><label class="checkbox"><input id="layer-visible" type="checkbox" ${l.visible?'checked':''}>화면에 표시</label></div><div class="layers-help" style="padding:0">왼쪽 레이어나 캔버스를 클릭하면 해당 요소만 편집합니다.</div>`}
const settingsEditor=editor;editor=function(p=false){if(p||['수집·동의','경품','참여 규칙','현장 안내'].includes(state.editorTab))return settingsEditor(p);return shell(`${steps('editor')}<div class="studio-toolbar"><div><h2>게임 디자인</h2><span class="mini-label">${currentTemplate().title} · 직접 편집</span></div><div class="studio-pages">${['참여 시작','게임','결과'].map(t=>`<button class="${state.studioPage===t?'active':''}" data-studiopage="${t}">${t}</button>`).join('')}</div><div class="inline"><button class="btn secondary" data-studio="settings">수집·동의</button><a class="btn secondary" href="#prizes">경품 설정</a></div></div>${state.aiLayerDraft?`<div class="alert purple">AI 수정 초안: ${esc(state.aiLayerDraft)}<div class="inline mt"><button class="btn soft" data-studio="apply-ai">제목에 적용</button><button class="btn secondary" data-studio="discard-ai">취소</button></div></div>`:''}<div class="studio-layout"><aside class="layers-panel"><div class="layers-title">레이어 <span class="mini-label">${state.layers.length}</span></div>${state.layers.map(l=>`<div class="layer-item ${state.layerId===l.id?'active':''} ${l.visible?'':'hidden-layer'}"><span class="layer-icon">${l.id==='game'?'◇':l.id==='button'?'▭':'T'}</span><button class="layer-select" data-layer="${l.id}">${esc(l.name)}</button><button data-togglelayer="${l.id}" aria-label="${l.name} 표시 전환">${l.visible?'◉':'○'}</button></div>`).join('')}<div class="layer-controls"><button data-studio="up" aria-label="레이어 위로">↑</button><button data-studio="down" aria-label="레이어 아래로">↓</button><button data-studio="undo">되돌리기</button></div><p class="layers-help">레이어를 선택하거나<br>화면 요소를 직접 클릭하세요.</p></aside><section class="studio-canvas"><div class="canvas-caption"><span>모바일 캔버스</span><span>100%</span></div><div id="layer-canvas">${layerCanvas()}</div><p class="mini-label mt">실시간 반영 · ${currentBrand().name}</p></section><aside class="properties-panel" id="layer-properties">${properties()}</aside></div><details class="studio-ai"><summary>✧ AI로 수정 요청하기</summary><textarea id="studio-prompt" placeholder="예: 제목을 ‘루미에르의 작은 선물’로 바꿔줘."></textarea><button class="btn soft mt" data-studio="ai">수정 초안 만들기</button></details><div class="studio-bottom"><a class="text-link" href="#templates">← 다른 템플릿 선택</a><span class="dim small">텍스트·색상 변경은 즉시 반영됩니다.</span><div class="inline"><button class="btn secondary" data-action="save">저장</button><button class="btn" data-action="to-review">검토로 이동 →</button></div></div>`)};
const checkoutSource=publish;function checkout(){let h=checkoutSource();h=h.replace(/<div class="event-header">[\s\S]*?<div class="steps">[\s\S]*?<\/div>/,`<a href="#publish" class="billing-back">← 게시 준비로 돌아가기</a>${title('EVENT PASS','행사 패스·결제','운영할 행사에 행사 패스을 활성화합니다. 게시 설정과 별도로 관리됩니다.')}`);h=h.replace('시연 결제 후 게시','행사 패스 활성화');return h}
publish=function(){if(state.published){return shell(`${steps('publish')}<div class="publish-clean">${statusNotice('게시 완료','참여 링크와 QR이 준비되었습니다.')}<section class="panel" style="text-align:center"><h2>${esc(state.eventName||'루미에르 성수 팝업 룰렛')}</h2>${qr()}<p class="mini-label">QR 또는 링크로 참여할 수 있습니다.</p><div class="inline"><input readonly value="${esc(location.origin+location.pathname+'#start')}"><button class="btn secondary" data-action="copy-participant">복사</button></div><div class="inline mt" style="justify-content:center"><a class="btn" href="#operate">운영 모니터 →</a><a class="btn secondary" href="#start">참여 화면 열기</a></div></section></div>`)}return shell(`${steps('publish')}<div class="publish-clean"><div class="publish-heading"><h2>참여자를 만날 준비를 해요.</h2><p class="sub mt">시안과 운영 설정을 확인한 뒤 행사를 게시합니다.</p></div><section class="panel"><h3>게시 전 확인</h3><div class="readiness-row"><div>시안 확정<small>현재 버전을 브랜드사와 확인합니다.</small></div>${state.approved?'<span class="ready-check">✓ 확정 완료</span>':'<a href="#brand-review" class="text-link">시안 확인 →</a>'}</div><div class="readiness-row"><div>수집·동의 문구<small>참여자에게 보여줄 문구를 확인합니다.</small></div>${state.consent?'<span class="ready-check">✓ 확인 완료</span>':'<button data-studio="settings" class="text-link">설정 확인 →</button>'}</div><div class="readiness-row"><div>경품과 지급 방식<small>경품 수량·확률·모바일 발송·현장 수령</small></div><a href="#prizes" class="text-link">설정 보기 →</a></div></section><section class="panel publish-settings"><h3>게시 설정</h3><div class="grid cols-2"><div class="field"><label>행사명</label><input readonly value="${esc(state.eventName||'루미에르 성수 팝업 룰렛')}"></div><div class="field"><label>운영 기간</label><input readonly value="${esc(state.basic.start?state.basic.start+' '+(state.basic.startTime||'10:00'):'10월 12일')} — ${esc(state.basic.end?state.basic.end+' '+(state.basic.endTime||'16:00'):'10월 16일')}"></div></div><div class="mini-label">게시 후 참여 링크와 QR이 생성됩니다.</div></section><div class="pass-status"><div><strong>행사 패스</strong><p>${state.paid?'이 행사에 행사 패스이 활성화되어 있습니다.':'아직 활성화되지 않았습니다. 행사 패스 관리에서 준비해주세요.'}</p></div>${state.paid?'<span class="ready-check">✓ 활성화됨</span>':'<a href="#checkout" class="btn secondary">행사 패스 관리 →</a>'}</div><div class="studio-bottom"><span class="mini-label">확정·동의 확인·행사 패스 활성화 후 게시할 수 있습니다.</span><button class="btn" data-studio="publish">행사 게시 →</button></div></div>`)};
function selectScope(id){state.brandId=id;const r=route();if(['editor','prizes','review','publish','operate','report','checkout'].includes(r)){state.eventName='';state.creationCustom=false;go('workspace-detail')}else if(r==='workspace-detail')render();else if(r==='home'||r==='events'){state.brandFilter=id;render()}else render()}
function snapshotLayers(){state.layerHistory.push(JSON.parse(JSON.stringify(state.layers)))}
function changeLayer(key,value){snapshotLayers();const l=state.layers.find(l=>l.id===state.layerId);l[key]=value;document.getElementById('layer-canvas').innerHTML=layerCanvas();bindStudio();}
function bindStudio(){app.querySelectorAll('[data-layer]').forEach(n=>n.onclick=()=>{state.layerId=n.dataset.layer;render()});app.querySelectorAll('[data-togglelayer]').forEach(n=>n.onclick=()=>{snapshotLayers();const l=state.layers.find(l=>l.id===n.dataset.togglelayer);l.visible=!l.visible;render()});app.querySelectorAll('[data-studiopage]').forEach(n=>n.onclick=()=>{state.studioPage=n.dataset.studiopage;render()});app.querySelectorAll('[data-studio]').forEach(n=>n.onclick=()=>studioAction(n.dataset.studio));const txt=document.getElementById('layer-text');if(txt)txt.oninput=()=>changeLayer('text',txt.value);const color=document.getElementById('layer-color');if(color)color.oninput=()=>{changeLayer('color',color.value);document.getElementById('layer-color-hex').value=color.value};const size=document.getElementById('layer-size');if(size)size.oninput=()=>changeLayer('size',Math.max(8,Math.min(48,+size.value||12)));const vis=document.getElementById('layer-visible');if(vis)vis.onchange=()=>{changeLayer('visible',vis.checked);render()};const scope=document.getElementById('scope-brand');if(scope)scope.onchange=()=>selectScope(scope.value)}
function studioAction(a){if(a==='apply-ai'){snapshotLayers();state.layers.find(l=>l.id==='title').text=state.aiLayerDraft;state.aiLayerDraft='';state.layerId='title';render();return}if(a==='discard-ai'){state.aiLayerDraft='';render();return}if(a==='settings'){state.editorTab='수집·동의';go('editor');return}if(a==='publish'){if(!state.approved)return toast('브랜드사 시안 확정이 필요합니다.');if(!state.consent)return toast('수집·동의 문구를 확인해주세요.');if(!state.paid)return toast('먼저 행사 패스을 활성화해주세요.');state.published=true;render();toast('행사를 게시했습니다.');return}if(a==='undo'){if(!state.layerHistory.length)return toast('되돌릴 변경이 없습니다.');state.layers=state.layerHistory.pop();render();return}if(a==='up'||a==='down'){let i=state.layers.findIndex(l=>l.id===state.layerId),j=i+(a==='up'?-1:1);if(j<0||j>=state.layers.length)return;snapshotLayers();[state.layers[i],state.layers[j]]=[state.layers[j],state.layers[i]];render();return}if(a==='ai'){const p=document.getElementById('studio-prompt').value;if(!p.trim())return toast('수정할 내용을 입력해주세요.');const match=p.match(/[‘'“"]([^’'”"]+)[’'”"]/);if(!match)return toast('시연에서는 바꿀 제목을 따옴표로 입력해주세요.');snapshotLayers();state.layers.find(l=>l.id==='title').text=match[1];state.layerId='title';render();toast('제목 수정 초안을 적용했습니다. 되돌리기할 수 있습니다.')}}
const studioBind=bind;bind=function(){studioBind();bindStudio()};const studioUse=useTemplate;useTemplate=function(id){state.selectedTemplate=id;resetLayers();state.editorTab='디자인';studioUse(id)};const studioActionOriginal=action;action=function(a,n){if(a==='pay'){if(!state.approved)return toast('시안 확정 후 행사 패스을 활성화해주세요.');if(!document.getElementById('cost-check')?.checked)return toast('비용과 초과 정산 조건을 확인해주세요.');state.paid=true;state.published=false;go('publish');toast('시연 결제 완료 · 행사 패스 활성화. 게시 버튼으로 공개해주세요.');return}studioActionOriginal(a,n)};
screens.splice(screens.findIndex(s=>s[0]==='publish')+1,0,['checkout','C-BILL','행사 패스·결제']);const studioRender=render;render=function(){if(route()==='checkout'){app.innerHTML=checkout();document.body.dataset.screen='checkout';bind()}else studioRender()};render();

const studioCreateAction=createAction;createAction=function(a){studioCreateAction(a);if(a==='generate'&&route()==='editor'){resetLayers();render()}};
